-- AQARI V267 Preview/Staging: extend official forms with a source-bound exit notice.
do $r$ begin if to_regprocedure('private.aqari_official_template_pre_exit_20260915(text)') is null then alter function private.aqari_official_template(text) rename to aqari_official_template_pre_exit_20260915;end if;if to_regprocedure('private.aqari_official_source_pre_exit_20260915(uuid,text,text,uuid,uuid,jsonb)') is null then alter function private.aqari_official_source(uuid,text,text,uuid,uuid,jsonb) rename to aqari_official_source_pre_exit_20260915;end if;end $r$;
create or replace function private.aqari_official_template(k text) returns jsonb language sql immutable security invoker set search_path='' as $$select case when k='exit_notice' then jsonb_build_object('title','إشعار إخلاء','prefix','EXIT','required',jsonb_build_array('documentNo','issuedAt','tenantName','propertyName','unitNo','contractNo','vacateDate'),'body','نفيد السيد/السيدة {{tenantName}} بأن موعد إخلاء وتسليم الوحدة {{unitNo}} في {{propertyName}} المرتبطة بالعقد رقم {{contractNo}} مسجل بتاريخ {{vacateDate}}. يخضع إقفال الالتزامات والتأمين والمفاتيح والأضرار والخدمات للتسوية النهائية المحفوظة في النظام.','immutableAfterIssue',true,'version',1) else private.aqari_official_template_pre_exit_20260915(k) end$$;
revoke all on function private.aqari_official_template(text) from public,anon,authenticated;
create or replace function private.aqari_official_source(w uuid,k text,t text,i uuid,source_id uuid,fields jsonb default '{}') returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;begin if k<>'exit_notice' then return private.aqari_official_source_pre_exit_20260915(w,k,t,i,source_id,fields);end if;if t is distinct from 'lease' then raise exception 'DOCUMENT_KIND_ENTITY_MISMATCH' using errcode='22023';end if;if source_id is not null then raise exception 'DOCUMENT_SOURCE_NOT_EXPECTED' using errcode='22023';end if;if not private.aqari_official_entity_scope(w,'lease',i,'read') then raise insufficient_privilege using message='DOCUMENT_ENTITY_NOT_FOUND';end if;select jsonb_build_object('tenantName',q.full_name,'propertyName',p.name,'unitNo',u.unit_no,'contractNo',l.contract_no,'vacateDate',s.vacate_date::text) into result from public.aqari_leases l join public.aqari_tenants q on q.workspace_id=l.workspace_id and q.id=l.tenant_id join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id join public.aqari_properties p on p.workspace_id=u.workspace_id and p.id=u.property_id join private.aqari_vacating_settlements s on s.workspace_id=l.workspace_id and s.lease_id=l.id where l.workspace_id=w and l.id=i and l.status in('signed','expired');if result is null then raise exception 'DOCUMENT_VACATING_RECORD_REQUIRED' using errcode='23514';end if;return result;end$$;
revoke all on function private.aqari_official_source(uuid,text,text,uuid,uuid,jsonb) from public,anon,authenticated;
